<template><section class="scr-card"><label>{{ t('garage.importJson') }}<textarea v-model="importText" maxlength="131072"></textarea></label><div class="scr-actions"><button type="button" :disabled="!validImport" @click="submitImport">{{ t('common.import') }}</button><button type="button" :disabled="!selectedId" @click="stores.command.send('exportVehicleDNAJson', [selectedId, false])">{{ t('garage.exportJson') }}</button><button type="button" :disabled="!selectedId" @click="stores.command.send('exportVehicleDNAPackage', [selectedId])">{{ t('garage.exportPackage') }}</button><button type="button" @click="stores.command.send('importVehicleDNAPackage', ['inbox'])">{{ t('garage.previewPackage') }}</button><button type="button" :disabled="!garage.importPreview" @click="confirmPackage">{{ t('garage.confirmPackage') }}</button></div><label v-if="garage.exportText">{{ t('common.export') }}<textarea readonly :value="garage.exportText"></textarea></label><pre v-if="garage.importPreview">{{ JSON.stringify(garage.importPreview, null, 2) }}</pre></section></template>
<script setup>
import { computed, ref } from "vue"; import { useStores } from "../../stores/index.js"; import { confirmDialog } from "../../services/dialogs.js"
const stores = useStores(); const garage = stores.garage.state; const { t } = stores.i18n; const importText = ref(""); const selectedId = computed(() => garage.selectedId || garage.entries?.[0]?.id || "")
const parsed = computed(() => { try { const value = JSON.parse(importText.value); return value && !Array.isArray(value) && typeof value === "object" ? value : null } catch { return null } }); const validImport = computed(() => importText.value.length > 0 && importText.value.length <= 131072 && !!parsed.value)
function submitImport() { if (parsed.value) { stores.command.send("importVehicleDNA", [parsed.value]); importText.value = "" } }
async function confirmPackage() { if (await confirmDialog(stores.uiLayout.state, t("garage.confirmPackage"), t("garage.confirmPackagePrompt"))) stores.command.send("confirmVehicleDNAPackageImport") }
</script>
